function dir$allsmail(p){
  this.constructor(p);
    document._dir = p;
}
dir$allsmail.prototype = new DirEvent();
dir$allsmail.prototype.beforeInit = function(renderType){
  this._dir.options._files = null;
}

dir$allsmail.prototype.afterInit = function(renderType){
	var p = this._dir, g = p.grid();
	dir$allsmailDisabledMasterField(p, g);
	dir$allsmailHiddenColumnByType(p);
	dir$allsmailHiddenColumnByTran(p);
	dir$allsmailDisabledStatusByAction(p);
}

dir$allsmail.prototype.beforeButtonDialogClick = function (id) {
	var p = this._dir;

	if (id === 'ok') {
		var d = p.valForm('ngay_hl'), d2 = p.valForm('ngay_hld');
		var k = $.date(d, "dd/mm/yy"), k2 = $.date(d2, "dd/mm/yy");

		if (p.valForm('ngay_hld') <= p.valForm('ngay_hl')) {
			$.alert(p.msg('noDate') + ' ' + k + ' < ' + k2);
			return false;
		}
	}

	return true;
};

