}
dir$allsmail.prototype.gridDetailActionChange = function(gindex, action, r){
  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$allsmailDisabledMasterField(p, p.grid(gindex));
  return true;
}
